render_chart <- function(data, cfg, manifest) { chart_validate_columns(data, list(from = cfg$x, to = cfg$y), c("from", "to")); from_values <- as.character(data[[cfg$x]]); to_values <- as.character(data[[cfg$y]]); left <- sort(unique(from_values)); right <- sort(unique(to_values)); chart_open_device(cfg$outputPath, cfg$format); plot(NA, xlim = c(0, 1), ylim = c(0, 1), axes = FALSE, xlab = "", ylab = "", main = cfg$title %||% "连接图"); ly <- seq(0.1, 0.9, length.out = length(left)); ry <- seq(0.1, 0.9, length.out = length(right)); names(ly) <- left; names(ry) <- right; points(rep(0.1, length(ly)), ly, pch = 21, bg = "white", col = cfg$color %||% "#0A84FF", cex = 2); points(rep(0.9, length(ry)), ry, pch = 21, bg = "white", col = cfg$color %||% "#0A84FF", cex = 2); text(0.06, ly, left, adj = 1, xpd = TRUE); text(0.94, ry, right, adj = 0, xpd = TRUE); for (i in seq_len(nrow(data))) segments(0.1, ly[from_values[i]], 0.9, ry[to_values[i]], col = grDevices::adjustcolor(cfg$color %||% "#0A84FF", alpha.f = 0.35)); box(); grDevices::dev.off(); cfg$outputPath }
